package org.apache.commons.math.geometry.euclidean.threed;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for Rotation constructor using two vectors.
 */
public class Rotation_Rotation_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testConstructorZeroNormThrowsException() {
        Vector3D u1 = Vector3D.ZERO;
        Vector3D u2 = new Vector3D(1, 0, 0);
        Vector3D v1 = new Vector3D(0, 1, 0);
        Vector3D v2 = new Vector3D(0, 0, 1);

        assertThrows(MathRuntimeException.class, () -> new Rotation(u1, u2, v1, v2));
    }

    @Test
    public void testConstructorIdentity() {
        // If u = v, it should result in an identity rotation
        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        Vector3D v1 = new Vector3D(1, 0, 0);
        Vector3D v2 = new Vector3D(0, 1, 0);

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        assertEquals(1.0, rotation.getQ0(), EPSILON);
        assertEquals(0.0, rotation.getQ1(), EPSILON);
        assertEquals(0.0, rotation.getQ2(), EPSILON);
        assertEquals(0.0, rotation.getQ3(), EPSILON);
    }

    @Test
    public void testConstructorStandardRotation() {
        // Rotate 90 degrees around Z axis
        // u1=(1,0,0), u2=(0,1,0) -> v1=(0,1,0), v2=(-1,0,0)
        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        Vector3D v1 = new Vector3D(0, 1, 0);
        Vector3D v2 = new Vector3D(-1, 0, 0);

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        // Expected rotation matrix for 90 deg Z: [[0, -1, 0], [1, 0, 0], [0, 0, 1]]
        // Quaternion for 90 deg Z: q0=cos(45)=0.707, q3=sin(45)=0.707
        assertEquals(0.70710678118, rotation.getQ0(), 1e-6);
        assertEquals(0.0, rotation.getQ1(), 1e-6);
        assertEquals(0.0, rotation.getQ2(), 1e-6);
        assertEquals(0.70710678118, rotation.getQ3(), 1e-6);
    }

    @Test
    public void testConstructorSingularityCase1() {
        // This test targets the 'if (c == 0)' branch where the first attempt fails
        // We want k.dotProduct(u3) to be 0.
        // u1, u2 define a plane. v1, v2 are in that same plane, but offset.
        // However, the logic tries to find a new basis if the cross products align.

        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        // v1, v2 in the same plane as u1, u2 but shifted such that c=0
        // Let's ensure the cross product k is perpendicular to u3.
        // u3 = u1 x u2 = (0,0,1). We need k.z = 0.
        // k = (v1-u1) x (v2-u2). 
        // Let v1-u1 = (0, 1, 0) -> v1 = (1, 1, 0)
        // Let v2-u2 = (1, 0, 0) -> v2 = (1, 1, 0) -> this makes v1=v2, but we need v2v2 != 0
        // Let's use:
        Vector3D v1_raw = new Vector3D(1, 1, 0);
        Vector3D v2_raw = new Vector3D(1, 2, 0);

        Rotation rotation = new Rotation(u1, u2, v1_raw, v2_raw);
        // If it didn't crash, it handled the branch.
        assertTrue(Math.abs(rotation.getAngle()) < Math.PI);
    }

    @Test
    public void testConstructorSingularityCase2() {
        // Targets the second nested if (c == 0)
        // We need the first attempt to fail and the second attempt (with v3) to fail.
        // This happens when the rotation is extremely close to u1.

        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        // v1 very close to u1
        Vector3D v1 = new Vector3D(1, 0.00000001, 0);
        // v2 very close to u2
        Vector3D v2 = new Vector3D(0, 1, 0.00000001);

        Rotation rotation = new Rotation(u1, u2, v1, v2);
        assertEquals(1.0, rotation.getQ0(), 1e-5);
    }

    @Test
    public void testConstructorSingularityCase3() {
        // Targets the third nested if (c == 0)
        // This covers the case where the rotation is almost the identity 
        // but follows the complex logic path.

        Vector3D u1 = new Vector3D(1, 0, 0);
        Vector3D u2 = new Vector3D(0, 1, 0);
        // Very specific vectors to force the code into the deep nested if
        // where it falls through to the identity q0=1.0
        Vector3D v1 = new Vector3D(1, 0, 0);
        Vector3D v2 = new Vector3D(0, 1, 0);

        Rotation rotation = new Rotation(u1, u2, v1, v2);
        assertEquals(1.0, rotation.getQ0(), EPSILON);
        assertEquals(0.0, rotation.getQ1(), EPSILON);
    }

    @Test
    public void testNonOrthogonalVectors() {
        // Test with vectors that are not orthogonal to ensure normalization/adjustment logic works
        Vector3D u1 = new Vector3D(2, 0, 0);
        Vector3D u2 = new Vector3D(1, 1, 0);
        Vector3D v1 = new Vector3D(0, 2, 0);
        Vector3D v2 = new Vector3D(1, 0, 1);

        Rotation rotation = new Rotation(u1, u2, v1, v2);

        // Verify that applying the rotation to u1 results in v1 (normalized correctly)
        // The constructor ensures (v1'|v1') = (u1|u1)
        Vector3D resultU1 = rotation.applyTo(u1);
        // The transformation should map u1 to a vector with same norm as v1 (after scaling)
        // In the code: v1 = new Vector3D(sqrt(u1u1/v1v1), v1);
        // So |v1_new| = sqrt(u1u1/v1v1) * |v1| = sqrt(u1u1) = |u1|.
        // Wait, the logic is v1_new = scaling * v1.
        // The resulting vector should have norm equal to u1's norm.
        assertEquals(u1.getNorm(), resultU1.getNorm(), EPSILON);
    }
}
